 private void chooseQuality(){final int token=generation;task(()->{WallpaperSource file=null;String name="Sin imagen";if(prefs.getString("wallpaper_mode","original").equals("daily"))file=WallpaperOnline.file(this);else{WallpaperStore.Photo p=store.find(prefs.getString("wallpaper_photo",""));if(p==null){List<WallpaperStore.Photo> list=WallpaperSelection.eligible(prefs,store.photos());if(!list.isEmpty()&&prefs.getString("wallpaper_mode","original").equals("slideshow"))p=list.get(0);}if(p!=null){file=p.file;name=p.name;}}String stored="Sin imagen guardada";if(file!=null){int[] d=dimensions(file);stored=d[0]+" × "+d[1]+" · "+WallpaperImages.bytes(file.length());}final String detail="Inicio de Android: "+WallpaperImages.screenWidth(this)+" × "+WallpaperImages.screenHeight(this)+"\nFondo utilizado: hasta "+WallpaperImages.label(WallpaperImages.usable(this,prefs.getString("wallpaper_quality","auto"))>=3840?"ultra":WallpaperImages.usable(this,prefs.getString("wallpaper_quality","auto"))>=1920?"balanced":"light")+"\nArchivo guardado: "+stored+"\n\nEsto no indica la resolución máxima del TV Box ni la resolución nativa del televisor. Más resolución no recupera detalle de una foto pequeña.";ui.post(()->{if(!foreground||token!=generation)return;List<String> options=WallpaperImages.qualities(this);AlertDialog.Builder dialog=new AlertDialog.Builder(this).setTitle("Resolución del fondo").setMessage(detail).setNegativeButton("Volver",null);if(options.size()>2)dialog.setPositiveButton("Elegir resolución",(d,w)->{String[] labels=new String[options.size()];for(int i=0;i<labels.length;i++)labels[i]=options.get(i).equals("auto")?"Automática · recomendada":WallpaperImages.label(options.get(i));new AlertDialog.Builder(this).setTitle("Resolución para este inicio").setItems(labels,(x,i)->{prefs.edit().putString("wallpaper_quality",options.get(i)).apply();main();}).setNegativeButton("Volver",null).show();});dialog.show();});});}

