 private void loadComparison(){final int token=++generation;final String quality=compareQuality;ImageView view=previewView;if(view==null)return;view.setImageDrawable(null);if(preview!=null){preview.recycle();preview=null;}compareHud.setText("Preparando "+WallpaperImages.label(quality)+"…\n"+comparisonHint());worker.getQueue().clear();task(()->{try{WallpaperStore.Photo p=store.find(photoId);WallpaperSource selected=p==null&&photoId.equals("daily")?WallpaperOnline.file(this):p==null?null:p.file;if(selected==null)throw new IOException("Imagen no disponible");WallpaperImages.Rendered result=WallpaperImages.render(this,selected,quality,memoryReduced);ui.post(()->{if(!foreground||!page.equals("compare")||token!=generation){result.bitmap.recycle();return;}preview=result.bitmap;compareActual=result.quality;compareWarning=result.warning;view.setScaleType(result.contain?ImageView.ScaleType.FIT_CENTER:ImageView.ScaleType.CENTER_CROP);view.setImageBitmap(preview);compareHud.setText(WallpaperImages.label(quality)+" · imagen "+preview.getWidth()+" × "+preview.getHeight()+"\n"+(result.warning.isEmpty()?"":result.warning+"\n")+comparisonHint());});}catch(Exception e){ui.post(()->{if(foreground&&token==generation)compareHud.setText("No se pudo cargar: "+e.getMessage()+"\nAtrás para volver");});}});}
