 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);returningPicker=false;if(request!=41)return;if(result!=RESULT_OK||data==null){page="main";return;}ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<Math.min(50,data.getClipData().getItemCount());i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());List<WallpaperImports.Item> items=new ArrayList<>();for(int i=0;i<uris.size();i++){Uri uri=uris.get(i);boolean release=false;if((data.getFlags()&Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION)!=0){boolean existed=false;for(UriPermission permission:getContentResolver().getPersistedUriPermissions())if(permission.getUri().equals(uri)&&permission.isReadPermission())existed=true;if(!existed)try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);release=true;}catch(SecurityException ignored){}}items.add(new WallpaperImports.Item(uri,"Imagen "+(i+1),release));}startImport(items);}
